primaryQuery:
run: order_items -> {
  where: status = 'Returned'
  aggregate:
    returned_items is count()
    returned_at_equals_created_at is count() { where: returned_at = created_at }
    naive_days_delivered_to_returned is round(avg(days(delivered_at to returned_at::date)), 4)
}

verifyQuery:
run: order_items -> {
  where: status = 'Returned'
  group_by: ret_month is returned_at.month
  aggregate:
    n is count()
    n_same is count() { where: returned_at = created_at }
    n_with_delivery is count() { where: delivered_at is not null }
    gap_days is sum(days(delivered_at to returned_at::date))
} -> {
  aggregate:
    returned_items is n.sum()
    returned_at_equals_created_at is n_same.sum()
    total_gap is gap_days.sum()
    n_del is n_with_delivery.sum()
} -> {
  select:
    returned_items
    returned_at_equals_created_at
    naive_days_delivered_to_returned is round(total_gap / n_del, 4)
}
